import os
from google.cloud import documentai_v1 as documentai

def get_documentai_client():
    project_id = os.getenv("GOOGLE_CLOUD_PROJECT_ID")
    location = os.getenv("GOOGLE_CLOUD_LOCATION")
    # You might want to specify a processor_id here or pass it later
    # processor_id = os.getenv("GOOGLE_CLOUD_PROCESSOR_ID")

    if not project_id or not location:
        raise ValueError("GOOGLE_CLOUD_PROJECT_ID and GOOGLE_CLOUD_LOCATION environment variables must be set.")

    return documentai.DocumentProcessorServiceClient()

import os
from typing import Dict, Any
from google.cloud import documentai_v1 as documentai
from document_client import get_documentai_client
from document_models import Receipt, LineItem

def extract_receipt_fields(document_content: bytes, mime_type: str) -> Receipt:
    client = get_documentai_client()
    project_id = os.getenv("GOOGLE_CLOUD_PROJECT_ID")
    location = os.getenv("GOOGLE_CLOUD_LOCATION")
    processor_id = os.getenv("GOOGLE_CLOUD_RECEIPT_PROCESSOR_ID") # Specific processor for receipts

    if not processor_id:
        raise ValueError("GOOGLE_CLOUD_RECEIPT_PROCESSOR_ID environment variable must be set.")

    resource_name = client.processor_path(project_id, location, processor_id)

    raw_document = documentai.RawDocument(content=document_content, mime_type=mime_type)

    request = documentai.ProcessRequest(name=resource_name, raw_document=raw_document)

    result = client.process_document(request=request)
    document = result.document

    receipt = Receipt()

    for entity in document.entities:
        if entity.type == "merchant_name":
            receipt.merchant_name = entity.mention_text
        elif entity.type == "transaction_date":
            receipt.transaction_date = entity.mention_text
        elif entity.type == "total_amount":
            receipt.total_amount = float(entity.mention_text) if entity.mention_text else None
            if entity.normalized_value and entity.normalized_value.currency_symbol:
                receipt.currency = entity.normalized_value.currency_symbol
        elif entity.type == "total_tax": # Document AI often returns total_tax for receipts
            receipt.tax_amount = float(entity.mention_text) if entity.mention_text else None
        elif entity.type == "line_item":
            line_item = LineItem()
            for prop in entity.properties:
                if prop.type == "description":
                    line_item.description = prop.mention_text
                elif prop.type == "quantity":
                    line_item.quantity = float(prop.mention_text) if prop.mention_text else None
                elif prop.type == "unit_price":
                    line_item.unit_price = float(prop.mention_text) if prop.mention_text else None
                elif prop.type == "line_item_amount":
                    line_item.total_price = float(prop.mention_text) if prop.mention_text else None
            receipt.items.append(line_item)

    return receipt

import os
from typing import Dict, Any
import google.generativeai as genai
from normalize_expense import NormalizedExpense

def summarize_invoice_fields(normalized_invoice: Dict[str, Any]) -> str:
    # Configure the Google Gemini API
    gemini_api_key = os.getenv("GEMINI_API_KEY")
    if not gemini_api_key:
        raise ValueError("GEMINI_API_KEY environment variable must be set.")
    genai.configure(api_key=gemini_api_key)

    # Use the Gemini Pro model for summarization
    model = genai.GenerativeModel('gemini-pro') # Using a concrete model ID

    # Craft a prompt for summarization
    prompt = f"""Summarize the following invoice details in a concise paragraph, highlighting key information like vendor, total amount, and main line items. If no line items, mention just the total and vendor.

Invoice Details:
Vendor: {normalized_invoice.get('vendor_merchant_name', 'N/A')}
Date: {normalized_invoice.get('transaction_date', 'N/A')}
Total Amount: {normalized_invoice.get('total_amount', 'N/A')} {normalized_invoice.get('currency', '')}
Line Items: {', '.join([item.get('description', 'N/A') for item in normalized_invoice.get('items', [])]) if normalized_invoice.get('items') else 'No specific line items.'}
"""

    try:
        response = model.generate_content(prompt)
        return response.text
    except Exception as e:
        return f"Error summarizing invoice: {e}"

import os
from typing import Dict, Any
import google.cloud.firestore as firestore

def persist_expense_record(expense_record: Dict[str, Any], collection_name: str = "expense_records") -> Dict[str, Any]:
    # Initialize Firestore DB client
    # The GOOGLE_CLOUD_PROJECT_ID environment variable should be set for the client to infer the project.
    firestore_client = firestore.Client()

    # Add a new document to the specified collection
    # Firestore automatically creates the collection and document if they don't exist.
    try:
        doc_ref = firestore_client.collection(collection_name).add(expense_record)
        return {
            "status": "success",
            "document_id": doc_ref[1].id, # doc_ref is a tuple (timestamp, document_reference)
            "message": f"Expense record persisted with ID: {doc_ref[1].id}"
        }
    except Exception as e:
        return {
            "status": "error",
            "message": f"Failed to persist expense record: {e}"
        }
